  --stage-id: #2196F3;    /* Blue - Decode */
  --stage-ex: #FF9800;    /* Orange - Execute */
  --stage-mem: #9C27B0;   /* Purple - Memory */
  --stage-wb: #F44336;    /* Red - Write Back */
