}

.pipeline-stage[data-stage="ID"].active {
  border-color: var(--stage-id);
  background: color-mix(in srgb, var(--stage-id) 10%, white);
}

.pipeline-stage[data-stage="EX"].active {
  border-color: var(--stage-ex);
