/*
 * Visualization CSS - CPU Simulator View Components
 *
 * Defines layout and visual tokens for PipelineView, RegisterView, and ExecutionView.
 * Extends design-system.css with visualization-specific tokens.
 */

/* ============================================
 * VISUALIZATION COLOR TOKENS
 * ============================================ */

:root {
  /* Pipeline stage colors (5-stage RISC pipeline) */
  --stage-if-color: #4CAF50;   /* Instruction Fetch - Green */
  --stage-id-color: #2196F3;   /* Instruction Decode - Blue */
  --stage-ex-color: #FF9800;   /* Execute - Orange */
  --stage-mem-color: #9C27B0;  /* Memory Access - Purple */
  --stage-wb-color: #F44336;   /* Write Back - Red */

  /* Register change highlighting */
  --color-highlight-yellow: #FFF9C4;
}

/* ============================================
 * CPU VISUALIZER LAYOUT
 * ============================================ */

.cpu-visualizer {
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: 24px;
  padding: 24px;
}

/* Responsive: single column on mobile */
@media (max-width: 768px) {
  .cpu-visualizer {
    grid-template-columns: 1fr;
  }
}

/* ============================================
 * SECTION HEADINGS
 * ============================================ */

.pipeline-section h2,
.data-section h2 {
  font-size: var(--text-lg);
  margin-bottom: var(--space-sm);
  color: var(--color-text-heading);
}

/* ============================================
 * PIPELINE STAGES
 * ============================================ */

.pipeline-stages {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pipeline-stage {
  border: 1px solid var(--color-border);
  border-left: 4px solid var(--color-border);
  border-radius: 4px;
  padding: 12px;
  background: var(--color-surface);
  transition: box-shadow 0.2s ease, border-left-width 0.2s ease;
}

.pipeline-stage.active {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  border-left-width: 6px;
}

/* Stage-specific border colors */
.pipeline-stage[data-stage="IF"] {
  border-left-color: var(--stage-if-color);
}

.pipeline-stage[data-stage="ID"] {
  border-left-color: var(--stage-id-color);
}

.pipeline-stage[data-stage="EX"] {
  border-left-color: var(--stage-ex-color);
}

.pipeline-stage[data-stage="MEM"] {
  border-left-color: var(--stage-mem-color);
}

.pipeline-stage[data-stage="WB"] {
  border-left-color: var(--stage-wb-color);
}

/* Stage header layout */
.stage-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.stage-label {
  font-weight: bold;
  font-size: 14px;
}

.stage-name {
  font-size: 12px;
  color: var(--color-text-muted);
}

/* Instruction text */
.instruction-text {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--color-text);
}

/* ============================================
 * REGISTER GRID
 * ============================================ */

.register-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 8px;
}

.register-cell {
  border: 1px solid var(--color-border);
  border-radius: 4px;
  padding: 8px;
  background: var(--color-surface);
  transition: background-color 0.3s ease-out;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.register-cell.changed {
  background-color: var(--color-highlight-yellow);
}

/* Register $0 is hardwired to zero */
.register-cell[data-register="0"] {
  opacity: 0.6;
}

.register-label {
  font-weight: bold;
  font-size: 12px;
}

.register-value {
  font-family: var(--font-mono);
