/**
 * PipelineView - 5-stage pipeline visualization component
 *
 * Renders IF, ID, EX, MEM, WB pipeline stages with color-coded borders.
 * Displays instruction mnemonic + formatted operands for active stages.
 * Shows 'NOP' for inactive stages.
 *
 * Usage:
 *   const view = new PipelineView(containerElement);
 *   view.render(cpuState);
 */
(function() {
  'use strict';

  class PipelineView {
    /**
     * Creates a PipelineView instance
     * @param {HTMLElement} container - DOM element to render pipeline stages into
     */
    constructor(container) {
      this.container = container;
      this.stageElements = new Map();  // Fast stage lookup
      this.initializeStages();
    }

    /**
     * Creates the 5 pipeline stage cards in the DOM
     * Uses DocumentFragment for efficient batch insertion
     */
    initializeStages() {
      const stageNames = ['IF', 'ID', 'EX', 'MEM', 'WB'];
      const fullNames = {
        IF: 'Instruction Fetch',
        ID: 'Instruction Decode',
        EX: 'Execute',
        MEM: 'Memory Access',
        WB: 'Write Back'
      };

      const fragment = document.createDocumentFragment();

      stageNames.forEach(stageName => {
        const stageCard = document.createElement('div');
        stageCard.className = 'pipeline-stage';
        stageCard.dataset.stage = stageName;

        stageCard.innerHTML = `
          <div class="stage-header">
            <span class="stage-label">${stageName}</span>
            <span class="stage-name">${fullNames[stageName]}</span>
          </div>
          <div class="stage-content">
            <code class="instruction-text" data-stage-instruction>NOP</code>
          </div>
        `;

        this.stageElements.set(stageName, stageCard);
        fragment.appendChild(stageCard);
      });

      // Single DOM insertion for all stages
      this.container.appendChild(fragment);
    }

    /**
     * Renders the current pipeline state
     * @param {CPUState} state - Current CPU state with pipeline data
     */
    render(state) {
      const stageNames = ['IF', 'ID', 'EX', 'MEM', 'WB'];

      stageNames.forEach(stageName => {
        const stageData = state.pipeline[stageName];
        const stageCard = this.stageElements.get(stageName);
        const instructionEl = stageCard.querySelector('[data-stage-instruction]');

        if (stageData.active) {
          // Get instruction from IF stage (in non-pipelined mode, the instruction flows through all stages)
          // IF and ID stages store the instruction directly
          const instruction = state.pipeline.IF.instruction;

          if (instruction) {
            const displayText = `${instruction.mnemonic} ${this.formatOperands(instruction)}`.trim();
            instructionEl.textContent = displayText;
          } else {
            instructionEl.textContent = 'NOP';
          }

          stageCard.classList.add('active');
        } else {
          instructionEl.textContent = 'NOP';
          stageCard.classList.remove('active');
        }
      });
    }

    /**
     * Formats instruction operands for assembly-style display
     * @param {object} instruction - Instruction object with mnemonic, type, and operand fields
     * @returns {string} Formatted operand string
     * @private
     */
    formatOperands(instruction) {
      if (!instruction || instruction.mnemonic === 'NOP') {
        return '';
      }

      const { type, rs, rt, rd, immediate } = instruction;

      switch (type) {
        case 'R':
          // R-type: ADD $rd, $rs, $rt
          return `$${rd}, $${rs}, $${rt}`;

        case 'I':
          if (instruction.mnemonic === 'ADDI') {
            // ADDI $rt, $rs, imm
            return `$${rt}, $${rs}, ${immediate}`;
          } else if (instruction.mnemonic === 'LW') {
            // LW $rt, imm($rs)
            return `$${rt}, ${immediate}($${rs})`;
          }
          break;

        case 'S':
          // SW $rt, imm($rs)
          return `$${rt}, ${immediate}($${rs})`;

        case 'B':
          // BEQ $rs, $rt, offset
          return `$${rs}, $${rt}, ${immediate}`;

        case 'J':
          // J target
          return `${immediate}`;

        case 'NOP':
          return '';

        default:
          return '';
      }

      return '';
    }
  }

  // Export to global scope (vanilla JS pattern)
  if (typeof window !== 'undefined') {
    window.PipelineView = PipelineView;
  } else if (typeof global !== 'undefined') {
    global.PipelineView = PipelineView;
  }
})();

/**
 * RegisterView - 32-register grid visualization with change highlighting
 *
 * Renders 32 general-purpose registers ($0-$31) in a responsive grid.
 * Selectively updates only changed registers per frame for performance.
 * Applies CSS 'changed' class with yellow highlight for modified registers.
 * Register $0 shown with reduced opacity (hardwired to zero).
 *
 * Usage:
 *   const view = new RegisterView(containerElement);
 *   view.render(cpuState);
 */
(function() {
  'use strict';

  class RegisterView {
    /**
     * Creates a RegisterView instance
     * @param {HTMLElement} container - DOM element to render register grid into
     */
    constructor(container) {
      this.container = container;
      this.registerCells = [];  // Array of 32 DOM elements for O(1) access
      this._previousChanged = [];  // Track previous frame's changes for cleanup
      this._initialized = false;  // Track first render for full update
      this.initializeRegisters();
    }

    /**
     * Creates the 32 register cells in the DOM
     * Uses DocumentFragment for efficient batch insertion
     */
    initializeRegisters() {
      const fragment = document.createDocumentFragment();

      for (let i = 0; i < 32; i++) {
        const cell = document.createElement('div');
        cell.className = 'register-cell';
        cell.dataset.register = i;

        cell.innerHTML = `
          <span class="register-label">$${i}</span>
          <span class="register-value">0x00000000</span>
        `;

        this.registerCells.push(cell);
        fragment.appendChild(cell);
      }

      // Single DOM insertion for all register cells
      this.container.appendChild(fragment);
    }

    /**
     * Renders the current register state
     * Selectively updates only changed registers (not all 32)
     * @param {CPUState} state - Current CPU state with registers and changedRegisters
     */
    render(state) {
      // First render: update all register values
      if (!this._initialized) {
        for (let i = 0; i < 32; i++) {
          const cell = this.registerCells[i];
          const valueEl = cell.querySelector('.register-value');
          const value = state.registers[i];
          valueEl.textContent = '0x' + value.toString(16).toUpperCase().padStart(8, '0');
        }
        this._initialized = true;
        return;
      }

      // Remove 'changed' class from previous frame's highlighted registers
      this._previousChanged.forEach(index => {
        this.registerCells[index].classList.remove('changed');
      });

      // Convert Set to Array for iteration
      const changed = Array.from(state.changedRegisters || []);

      // Update only changed registers
      changed.forEach(index => {
        // Defensive: register $0 should never change due to setRegister protection
        // but handle it gracefully if it somehow appears in changedRegisters
        const cell = this.registerCells[index];
        const valueEl = cell.querySelector('.register-value');
        const value = index === 0 ? 0 : state.registers[index];

        valueEl.textContent = '0x' + value.toString(16).toUpperCase().padStart(8, '0');
        cell.classList.add('changed');
      });

      // Store for cleanup on next render
      this._previousChanged = changed;
    }
  }

  // Export to global scope (vanilla JS pattern)
  if (typeof window !== 'undefined') {
    window.RegisterView = RegisterView;
  } else if (typeof global !== 'undefined') {
    global.RegisterView = RegisterView;
  }
})();

/**
 * ExecutionView - Cycle and instruction counter display
 *
 * Displays execution metrics from CPUState:
 * - cycleCount: Total clock cycles executed
 * - instructionCount: Total instructions completed (written back)
 *
 * The container element should have aria-live="polite" for screen reader announcements
 * (set by parent CPUVisualizer in Plan 02).
 *
 * Usage:
 *   const view = new ExecutionView(containerElement);
 *   view.render(cpuState);
 */
(function() {
  'use strict';

  class ExecutionView {
    /**
     * Creates an ExecutionView instance
     * @param {HTMLElement} container - DOM element to render execution counters into
     */
    constructor(container) {
      this.container = container;
      this.initializeElements();
    }

    /**
     * Creates or queries the counter span elements
     * If container doesn't have the expected structure, creates it
     */
    initializeElements() {
      // Check if elements already exist
      this.cycleEl = this.container.querySelector('[data-cycle-count]');
      this.instructionEl = this.container.querySelector('[data-instruction-count]');

      // Create structure if elements don't exist
      if (!this.cycleEl || !this.instructionEl) {
        this.container.innerHTML = `
          <p>Cycle: <span data-cycle-count>0</span></p>
          <p>Instructions: <span data-instruction-count>0</span></p>
        `;

        // Re-query the newly created elements
        this.cycleEl = this.container.querySelector('[data-cycle-count]');
        this.instructionEl = this.container.querySelector('[data-instruction-count]');
      }
    }

    /**
     * Renders the current execution state
     * @param {CPUState} state - Current CPU state with cycleCount and instructionCount
     */
    render(state) {
      this.cycleEl.textContent = state.cycleCount;
      this.instructionEl.textContent = state.instructionCount;
    }
  }

  // Export to global scope (vanilla JS pattern)
  if (typeof window !== 'undefined') {
    window.ExecutionView = ExecutionView;
  } else if (typeof global !== 'undefined') {
    global.ExecutionView = ExecutionView;
  }
})();

